   csvwrite(run/f'feature_{m}_native_components.csv',fullrows)
   lines += ['For every row the numerical threshold is u·ai+v·ak>−q, with q=b1+Σ(nonpair C1·background); tabled p values implement all four inequalities, including sign reversals. If u,v>0, 11-only means −(u+v)<q≤−max(u,v). Always-on units can supply additive terms with zero interaction. Signed coefficients, not gate shape alone, determine the recovered latent.','']
